-- ============================================================================
-- V1: MySQL 迁移全量基线（2026-08-30 PG→MySQL 迁移，由线上 PG 库反向生成）
--
-- 来源：线上 Supabase PG 17.6（public schema，pg_dump --schema-only 导出后转换）
-- 转换：/tmp/pg2mysql.py（转换规则见 docs/pg-to-mysql-migration-analysis.md）
-- 策略：MySQL 环境放弃逐脚本翻译（V1-V61 为 PG 方言），全新库直接执行本基线
--       即达最新结构；数据从线上 PG pg_dump → 类型映射 → mysql load 搬运。
--
-- 关键转换决策：
-- 1. bigint GENERATED BY DEFAULT AS IDENTITY → bigint AUTO_INCREMENT，主键内联
--    PRIMARY KEY (id)（MySQL 要求 AUTO_INCREMENT 列必须为 key；本项目全表单列主键）
-- 2. boolean → tinyint(1)；timestamp without time zone → datetime(6)；double precision → double
-- 3. 部分唯一索引（PG WHERE 谓词）→ 生成列 uk_key_<idx> = IF(cond, MD5(...), NULL) STORED
--    + UNIQUE KEY——精确复刻语义：条件不满足行生成列=NULL 不受唯一约束
--    （MySQL UNIQUE 允许多个 NULL）。涉及表：venue_crowd_reports / venue_claims /
--    venue_feedbacks×2 / points_gates / points_transactions / dancer_services / tag_dict。
--    「单列 IS NOT NULL」形态（demand_records.rescue_origin）→ 全量 UNIQUE（语义等价）。
--    非唯一部分索引 → 全量索引（性能等价）。
-- 4. qwt_city_key(text) PG 函数 → MySQL DETERMINISTIC 函数（LEFT(city,-1)→LEFT(city,LENGTH(city)-1)）
-- 5. 保留字列名反引号：qwt_ops_config.key（MySQL KEY 保留字）
-- ============================================================================

-- Name: public; Type: SCHEMA; Schema: -; Owner: -
-- Name: SCHEMA public; Type: COMMENT; Schema: -; Owner: -
-- Name: qwt_city_key(text); Type: FUNCTION; Schema: public; Owner: -
-- qwt_city_key: 城市名规范化（去「市」后缀），供 native SQL 使用（DancerRepository）
CREATE FUNCTION qwt_city_key(city TEXT) RETURNS TEXT DETERMINISTIC
RETURN CASE WHEN RIGHT(city, 1) = '市' THEN LEFT(city, LENGTH(city) - 1) ELSE city END;

