-- Name: qwt_venue_feedbacks; Type: TABLE; Schema: public; Owner: -
CREATE TABLE qwt_venue_feedbacks (
    id bigint NOT NULL AUTO_INCREMENT,
    created_at datetime(6),
    deleted tinyint(1) NOT NULL,
    updated_at datetime(6),
    handled tinyint(1) NOT NULL,
    note varchar(500),
    type varchar(20) NOT NULL,
    user_id bigint,
    venue_id bigint NOT NULL,
    handled_at datetime(6),
    handled_by bigint,
    status varchar(20) DEFAULT 'PENDING' NOT NULL,
    handle_note varchar(500),
    field varchar(30),
    corrected_value varchar(500),
    uk_key_qwt_uk_feedbacks_user_venue_type_field_pending varchar(32) GENERATED ALWAYS AS (IF(((user_id IS NOT NULL) AND ((status) = 'PENDING') AND (field IS NOT NULL)), MD5(CONCAT_WS('#', COALESCE(CAST(user_id AS CHAR), '<n>'), COALESCE(CAST(venue_id AS CHAR), '<n>'), COALESCE(CAST(type AS CHAR), '<n>'), COALESCE(CAST(field AS CHAR), '<n>'))), NULL)) STORED,
    uk_key_qwt_uk_feedbacks_user_venue_type_pending varchar(32) GENERATED ALWAYS AS (IF(((user_id IS NOT NULL) AND ((status) = 'PENDING') AND (field IS NULL)), MD5(CONCAT_WS('#', COALESCE(CAST(user_id AS CHAR), '<n>'), COALESCE(CAST(venue_id AS CHAR), '<n>'), COALESCE(CAST(type AS CHAR), '<n>'))), NULL)) STORED,
    PRIMARY KEY (id)
);

